{"op":"add","path":"/root","value":"main"}
{"op":"add","path":"/elements/main","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg","align":"stretch"},"children":["intro","step-indicator","account-panel","preferences-panel","done-panel","wizard-actions"]}}
{"op":"add","path":"/elements/intro","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["title","description"]}}
{"op":"add","path":"/elements/title","value":{"type":"Heading","props":{"text":"Welcome — let’s get you set up","level":"h1"},"children":[]}}
{"op":"add","path":"/elements/description","value":{"type":"Text","props":{"text":"Complete these three quick steps to personalize your account.","variant":"lead"},"children":[]}}
{"op":"add","path":"/elements/step-indicator","value":{"type":"Card","props":{"title":{"$template":"Step ${/step} of 3"},"description":{"$cond":{"$state":"/step","eq":1},"$then":"Account","$else":{"$cond":{"$state":"/step","eq":2},"$then":"Preferences","$else":"Done"}}},"children":["progress"]}}
{"op":"add","path":"/elements/progress","value":{"type":"Progress","props":{"label":"Onboarding progress","value":{"$cond":{"$state":"/step","eq":1},"$then":33,"$else":{"$cond":{"$state":"/step","eq":2},"$then":66,"$else":100}}},"children":[]}}
{"op":"add","path":"/elements/account-panel","value":{"type":"Card","props":{"title":"Create your account","description":"Add your details to get started."},"visible":{"$state":"/step","eq":1},"children":["account-fields"]}}
{"op":"add","path":"/elements/account-fields","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["name-input","email-input","password-input"]}}
{"op":"add","path":"/elements/name-input","value":{"type":"Input","props":{"label":"Full name","placeholder":"Your name","value":{"$bindState":"/account/name"}},"children":[]}}
{"op":"add","path":"/state/account","value":{"name":"","email":"","password":""}}
{"op":"add","path":"/elements/email-input","value":{"type":"Input","props":{"label":"Email address","placeholder":"you@example.com","type":"email","value":{"$bindState":"/account/email"}},"children":[]}}
{"op":"add","path":"/elements/password-input","value":{"type":"Input","props":{"label":"Password","placeholder":"Create a secure password","type":"password","value":{"$bindState":"/account/password"}},"children":[]}}
{"op":"add","path":"/elements/preferences-panel","value":{"type":"Card","props":{"title":"Your preferences","description":"Choose how you’d like to hear from us."},"visible":{"$state":"/step","eq":2},"children":["preference-fields"]}}
{"op":"add","path":"/elements/preference-fields","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["topic-select","newsletter-switch"]}}
{"op":"add","path":"/elements/topic-select","value":{"type":"Select","props":{"label":"Topics you’re interested in","placeholder":"Choose a topic","options":["Product updates","Design","Engineering","Business"],"value":{"$bindState":"/preferences/topic"}},"children":[]}}
{"op":"add","path":"/state/preferences","value":{"topic":"Product updates","newsletter":true}}
{"op":"add","path":"/elements/newsletter-switch","value":{"type":"Switch","props":{"label":"Monthly newsletter","description":"Get a concise roundup of news and helpful tips.","checked":{"$bindState":"/preferences/newsletter"}},"children":[]}}
{"op":"add","path":"/elements/done-panel","value":{"type":"Card","props":{"title":"You’re all set","description":"Your account and preferences are ready. You can update these choices anytime in settings."},"visible":{"$state":"/step","eq":3},"children":["success-alert","summary"]}}
{"op":"add","path":"/elements/success-alert","value":{"type":"Alert","props":{"title":"Onboarding complete","description":"Thanks for joining us. Welcome aboard!","variant":"default"},"children":[]}}
{"op":"add","path":"/elements/summary","value":{"type":"Text","props":{"text":{"$template":"Account created for ${/account/name} · Interest: ${/preferences/topic}"},"variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/wizard-actions","value":{"type":"Stack","props":{"direction":"horizontal","gap":"md","align":"center"},"children":["back-button","next-button","finish-button"]}}
{"op":"add","path":"/elements/back-button","value":{"type":"Button","props":{"label":"Back","variant":"outline"},"visible":{"$state":"/step","gt":1},"on":{"press":{"action":"setState","params":{"statePath":"/step","value":{"$template":"${/step}"}}}},"children":[]}}
{"op":"add","path":"/elements/next-button","value":{"type":"Button","props":{"label":"Next","size":"default"},"visible":{"$state":"/step","lt":3},"on":{"press":{"action":"setState","params":{"statePath":"/step","value":{"$cond":{"$state":"/step","eq":1},"$then":2,"$else":3}}}},"children":[]}}
{"op":"add","path":"/elements/finish-button","value":{"type":"Button","props":{"label":"Finish","variant":"secondary"},"visible":{"$state":"/step","eq":3},"on":{"press":{"action":"setState","params":{"statePath":"/finished","value":true}}},"children":[]}}
{"op":"add","path":"/state/step","value":1}
{"op":"add","path":"/state/finished","value":false}
